  '36:niv1g-calcul': () => ['écart d’énergie entre deux niveaux', 'longueur d’onde d’un photon', 'énergie d’un photon absorbé ou émis', 'niveau d’arrivée', 'nombre de raies d’émission', 'domaine d’un photon'],
  '36:coul1g-calcul': () => ['mélange de lumières colorées', 'filtres colorés', 'couleur perçue d’un objet', 'radiations absorbées', 'sous-pixels d’un écran'],
