  '36:noy2gt-calcul': () => ['neutrons d’après ZAX', 'nombre de masse', 'charge du noyau', 'masse du noyau', 'atome et noyau agrandis', 'écriture conventionnelle ZAX'],
  '36:etat2gt-calcul': () => ['équation d’un changement d’état', 'énergie de changement d’état', 'masse qui change d’état', 'conversion d’unités', 'sens du transfert thermique', 'proportionnalité énergie et masse'],
  '36:nuc2gt-calcul': () => ['neutrons d’un noyau', 'nucléons d’un noyau', 'nature d’une transformation', 'fusion ou fission', 'neutrons libérés par une fission', 'chaîne d’une centrale'],
  '36:img2gt-calcul': () => ['rayons particuliers', 'hauteur de l’image', 'grandissement', 'conversion cm et m', 'position de l’image', 'hauteur de l’objet'],
  '36:test2gt-calcul': () => ['réactif et observation d’un test', 'lire une observation de test', 'nombre de tests nécessaires', 'durée des tests', 'deux espèces à la fois'],
  '36:comb1g-calcul': () => ['équation de combustion', 'énergies de liaison', 'énergie molaire de réaction', 'écart relatif', 'énergie libérée', 'pouvoir calorifique'],
