  '36:mes1g-calcul': () => ['moyenne et écart-type', 'incertitude-type de type A', 'incertitude-type de type B', 'arrondi d’une incertitude', 'compatibilité avec une référence'],
  '36:diss1g-calcul': () => ['équation de dissolution', 'concentration des ions', 'concentration d’une solution', 'quantités de matière', 'conversion d’unités'],
